  local executable=0
  for _,s in ipairs(image.sections)do
   local section={at=s.rva,len=s.size,read=s.read,exec=s.exec,write=s.write}
   sections[#sections+1]=section;if section.read and section.exec then executable=executable+section.len end
  end
