  local expected=(witness.hex:gsub('%x%x',function(v)return string.char(tonumber(v,16))end))
  assert(#expected==last-first and contains(first,#expected,'code'),'current stat witness extent rejected')
  local actual=observed(first,#expected);scan_bytes=#actual
  assert(actual==expected,'current stat full-function witness changed')
  assert(bridge.verify(),'stat adapter proof changed before semantic validation')
