    read(g+Grid.row_items,math.min(rows+1,Grid.row_capacity)*4),groups>0 and read(g+Grid.group_rows,groups*4)or '',
    groups>0 and read(g+Grid.group_items,groups*4)or '',groups>0 and read(g+Grid.group_keys,groups*4)or '',
