 -- Startup refresh uses the already-proven native player armor setter. It
 -- changes only the live request; the persisted game profile retains its
 -- ordinary carrier ID throughout the temporary switch and restoration.
 -- `menu_guard` is the headless caller's own answer to "may I drive the actor
 -- now": when given it replaces the idle-menu requirement, which belongs to the
 -- login restore alone. `scene_guard` likewise says where the actor is live.
 function self:player_refresh_bridge(player,catalog,data_bridge,scene_guard,menu_guard)
  local ok,result=pcall(function()
   local category=catalog.category or 0
   local field=({[Category.armor]='armor_id',[Category.helmet]='helmet_id',[Category.cape]='cape_id'})[category]
   local info=category==Category.armor and targets.deployment_commit or targets.player_commits and targets.player_commits[category]
   assert(self.phase=='ready'and info and code_current(),'native player armor setter unavailable')
   assert(info.profile_global==data_bridge.armor_catalog and data_bridge.verify(),
    'native armor manager proof differs')
   assert(type(scene_guard)=='function','startup scene guard required')
   assert(menu_guard==nil or type(menu_guard)=='function','invalid menu guard')
   local observations=setmetatable({},{__mode='k'})
   local function held()
    if not(code_current()and data_bridge.verify())then return 'native player armor proof changed'end
    if menu_guard then
     if menu_guard()~=true then return 'the Armory equipment screen is driving the actor'end
     if scene_guard()~=true then return 'the local actor is not live'end
    elseif not(self:idle_menu()==true and scene_guard()==true)then return 'startup restoration requires an idle ship'end
    return nil
   end
   local function guard()return held()==nil end
   local out={capabilities={commit_verified=true,cache_layout_verified=true,passive_cache_available=category~=Category.cape}}
   function out.snapshot()
    local why=held();if why then return nil,why end
    local actor,why=player:sample();if not actor then return nil,why end
    local slot=read(info.profile_global,8);local manager=assert(pointer(slot),'armor manager unavailable')
    local other={}
    for _,v in ipairs({actor.request,actor.current})do
     local values={v.body_type};for _,key in ipairs({'armor_id','helmet_id','cape_id'})do if key~=field then values[#values+1]=v[key]end end
     other[#other+1]=table.concat(values,'|')
    end
    local pending=other[1]~=other[2]
    local state={session=tostring(actor.session_key),other_key=table.concat(other,'|'),pending_nonarmor=pending,
     controller_armor_id=actor.request[field],profile_armor_id=actor.request[field],
     request_armor_id=actor.request[field],cache_armor_id=actor.current[field],
     cache_passive=category==Category.armor and actor.cache_passive_enum or category==Category.helmet and actor.cache_helmet_passive_enum or nil}
    local expected={};for k,v in pairs(state)do expected[k]=v end
    assert(guard()and actor.verify()and read(info.profile_global,8)==slot,'startup actor changed')
    observations[state]={actor=actor,slot=slot,manager=manager,expected=expected};return state
   end
   function out.verify(state)
    local saved=observations[state];if not saved or not guard()then return false end
    for k,v in pairs(saved.expected)do if state[k]~=v then return false end end
    for k,v in pairs(state)do if saved.expected[k]~=v then return false end end
    return read(info.profile_global,8)==saved.slot and saved.actor.verify()==true
   end
   function out.verify_owned(ids)return catalog.verify_owned(ids)==true end
   function out.owned_armors()
    local ids={}
    local source=catalog.native_owned or catalog.owned
    for id,owned in pairs(source)do
     local record=catalog.records and catalog.records[id]
     local managed=(catalog.registered and catalog.registered[id])or(catalog.thumbnail_donors and catalog.thumbnail_donors[id])
     if owned==true and type(id)=='string'and id:match('^armor:%x%x%x%x%x%x%x%x$')
      and (not managed or catalog.native_owned and catalog.native_owned[id]==true)
      and (record and record.category==category or not catalog.native_owned and not catalog.records)then
      ids[#ids+1]=id
     end
    end
    table.sort(ids);return ids
   end
   function out.commit_owned(id,state)
    local saved=observations[state]
    assert(saved and out.verify(state),'startup actor changed before native request')
    local record=catalog.records[id]
    assert(record and record.category==category and catalog.owned[id]and catalog.verify_owned({id}),
     'startup armor ownership changed')
    local calls=prepared()
    assert(calls.executable(info.entry)and type(calls.deployment_commit)=='function','native armor setter unavailable')
    assert(calls.deployment_commit(info.entry,saved.manager,saved.actor.local_player_id,record.item_id)~=false,
     'native startup armor request failed')
    local after,why=player:sample();assert(after,why)
    assert(after.session_key==saved.actor.session_key and after.request[field]==id,
     'startup armor request readback differs')
    for _,part in ipairs({'request','current'})do
     for _,key in ipairs({'body_type','armor_id','helmet_id','cape_id'})do
      if key~=field then assert(after[part][key]==saved.actor[part][key],'startup request changed other equipment')end
     end
    end
    assert(guard()and read(info.profile_global,8)==saved.slot,'startup context changed during native request')
    return true
   end
   return out
  end)
  if not ok then return nil,tostring(result)end;return result
 end
 function self:position(snapshot,x,y)
