   local ctx=assert(snapshots[snapshot],'grid context unavailable');local g=ctx.grid
   local manager=assert(pointer(read(assert(thumbnail_global,'thumbnail manager proof unavailable'),8)),'thumbnail manager unavailable')
   local raw=read(manager,Thumbs.size)
