      hexed(raw:sub(item+1,item+Thumbs.item_offer)),hexed(raw:sub(item+Thumbs.item_offer+9,item+Thumbs.item_rect)),hexed(raw:sub(item+Thumbs.item_rect+17,item+Thumbs.item_kind)),hexed(raw:sub(item+Thumbs.item_kind+5,item+Thumbs.item_stride)))
    end
   end
   local records=read(g+Grid.records,Grid.record_capacity*ImageRecord.size)
   for index=0,Grid.record_capacity-1 do
    local at=index*ImageRecord.size
