     lines[#lines+1]=string.format('record %d state=%d visual=%08x:%08x card=%d slot=%d flags=%d,%d style=%08x rest=%s',index,u32(records,at+ImageRecord.state),
      u32(records,at+ImageRecord.visual),u32(records,at+ImageRecord.visual_high),u32(records,at+ImageRecord.card),u32(records,at+ImageRecord.slot),records:byte(at+ImageRecord.flags+1),records:byte(at+ImageRecord.flags+2),u32(records,at+ImageRecord.style),
      hexed(records:sub(at+ImageRecord.state+5,at+ImageRecord.card)))
