    lines[#lines+1]=string.format('cell row=%d col=%d logical=%s ring=%s bound=%s alpha=%.2f named_material=%s',w.row,w.column,
     tostring(w.logical_index),tostring(w.ring_index),tostring(w.bound),w.image_alpha or -1,tostring(w.named_image_material))
   end
