  local ok,result=pcall(function()
   options=options or {};assert(type(options)=='table','native detail options required')
   assert(type(id)=='string'and id:match('^armor:%x%x%x%x%x%x%x%x$'),'stable armor identity required')
   local record=catalog_result and catalog_result.records and catalog_result.records[id]
   local donor=catalog_result and catalog_result.owned and catalog_result.owned[id]~=true
    and type(catalog_result.thumbnail_donors)=='table'and catalog_result.thumbnail_donors[id]or nil
   assert(record and record.category==(catalog_result.category or 0) and borrowable(catalog_result,id)
    and type(catalog_result.verify_owned)=='function'and catalog_result.verify_owned({id})==true,'fresh owned armor required')
   local calls=prepared()
   assert(targets.preview_details and calls.executable(targets.preview_details)
    and type(calls.preview_details)=='function','native detail preview unavailable')
   assert(options.requires_apply~=true or targets.detail_apply_hint,'native Apply presentation proof unavailable')
   local ctx=detail_context();local watch=ctx.watch
   local progression=assert(pointer(watch(assert(progression_global,'owned offer mapping unavailable'),8)),'progression unavailable')
   local count=u32(watch(progression+Progression.offer_count,4),0);assert(count>=1 and count<=Progression.offer_capacity,'offer bounds rejected')
   local worn_id=donor and type(options.worn_id)=='string'and options.worn_id or nil
   local worn_record=worn_id and catalog_result.records[worn_id]or nil
   local entries=watch(progression+Progression.offers,count*Progression.offer_stride);local matches={};local chosen,worn
   local function enabled(index,offer,as)
    assert(index<count,'owned offer index out of bounds')
    local state=progression+Progression.states+index*Progression.state_stride;local status=u32(watch(state+Progression.state_status,4),0)
    return((status==Progression.usable_a or status==Progression.usable_b)and watch(state+Progression.state_flag,1)=='\0')
     or(catalog_result.verify_registered and catalog_result.verify_registered(as,offer))
   end
   for i=0,count-1 do
    local at=i*Progression.offer_stride;local index,offer,kit=u32(entries,at+Progression.offer_index),u32(entries,at+Progression.offer_id),u32(entries,at+Progression.offer_kit)
    if offer~=0 then
     assert(not matches[offer]or matches[offer]==kit,'ambiguous native offer identity');matches[offer]=kit
