      elseif enabled(index,offer,id)then chosen=chosen or offer end
     elseif worn_record and kit==worn_record.item_id and enabled(index,offer,worn_id)then worn=worn or offer end
    end
   end
   assert(chosen,'no enabled owned offer for native details')
   local equipped=watch(ctx.preview_manager+Preview.equipped_offer,4)
   local profile=watch(ctx.profile_address,ctx.profile_size)
   local selected=watch(ctx.grid+Grid.selected_row,8);local highlighted=watch(ctx.grid+Grid.highlighted_offer,8)
   local scroll=watch(ctx.grid+Grid.scroll,8)
   local is_equipped=u32(equipped,0)==(donor and worn or chosen)and options.requires_apply~=true
   assert(ctx.unchanged()and code_current()and catalog_result.verify_owned({id})==true,'native detail context changed')
   report('grid.details.begin',id)
   local accepted=with_model(ctx.detail_widget+Detail.model+Model.kit,id,catalog_result,calls,function()
    return calls.preview_details(targets.preview_details,ctx.detail_widget,chosen,is_equipped)
   end)
   report('grid.details.returned',id)
   assert(accepted~=false,'native detail call rejected')
   local current=detail_context()
   assert(current.owner==ctx.owner and current.grid==ctx.grid,'native detail owner changed during notification')
   assert(read(ctx.profile_address,ctx.profile_size)==profile,'native details unexpectedly changed a profile or selection mirror')
   assert(read(ctx.grid+Grid.selected_row,8)==selected and read(ctx.grid+Grid.highlighted_offer,8)==highlighted
    and read(ctx.grid+Grid.scroll,8)==scroll,'native details unexpectedly changed grid focus or scroll')
   assert(u32(read(ctx.detail_widget+Detail.shown_offer,4),0)==chosen,'native detail offer readback differs')
   assert(ident(u32(read(ctx.detail_widget+Detail.model+Model.kit,4),0))==id,'native large preview kit readback differs')
   assert(code_current(),'native detail proof changed during notification')
   return {status='native_preview_readback_verified',kit_id=id,offer_id=chosen,
    native_detail_view=true,native_apply_pending=options.requires_apply==true,
