     local p=profiles['native-stats:'..id:sub(7)]
     local v=p and p.base_values_verified==true and p.base_values
     if category~=Category.armor then
      if not(p and p.weight_profile_verified and p.body_weights)then return nil end
      local values={}
      for _,body in ipairs(p.body_weights)do for _,piece in ipairs(body.pieces)do
       values[#values+1]=table.concat({body.body_type,piece.slot,piece.kind,piece.weight},':')
      end end
