     end
     return table.concat(values,':')
    end
    local wanted=tuple(stats_kit_id);local candidates={}
    for id,record in pairs(records)do
     if wanted and id~=stats_kit_id and catalog_result.owned[id]==true and record.category==category
      and tuple(id)==wanted and read(record.address,ArmorRecord.size)==record.bytes then candidates[#candidates+1]=id end
