    -- well: the game showing that one is the same model.
    local shown,why=self:detail_state()
    assert(shown and(shown.kit_id==model_id or shown.kit_id==appearance_id),why or 'Selected model changed before widget refresh')
    model_id=shown.kit_id
   else
