    assert(appearance_current(),'appearance changed before native model preview')
    local shown,error=self:preview_details(model_id,catalog_result,{requires_apply=options.requires_apply~=false,worn_id=appearance_id});assert(shown,error)
   end
   local ctx=detail_context();local watch=ctx.watch
   local offer,alternate,alternate_id,cached_passive
   if bind then
