    local count=u32(watch(progression+Progression.offer_count,4),0);assert(count>=1 and count<=Progression.offer_capacity,'offer bounds rejected')
    local entries=watch(progression+Progression.offers,count*Progression.offer_stride);local offers={}
    for i=0,count-1 do local at=i*Progression.offer_stride;local value,kit=u32(entries,at+Progression.offer_id),u32(entries,at+Progression.offer_kit)
     if value~=0 then assert(not offers[value]or offers[value]==kit,'ambiguous native offer identity');offers[value]=kit end
