 -- Presentation only, after the coordinator has confirmed the armor/passive
 -- cache. Do not re-enter native Apply or restart the appearance preview.
 -- `shown_id` is the record the model was built from when that is not the
 -- worn one: a saved card's own record, showing the look that was applied.
 function self:equipment_feedback(id,catalog_result,shown_id)
  local ok,result=pcall(function()
   local category=catalog_result.category or 0
   assert(category==Category.armor or category==Category.helmet or category==Category.cape,'unsupported equipment category')
   local audio=targets.equipment_audio
   assert(targets.equip_state and audio and code_current(),'native Equip feedback unavailable')
   local calls=prepared()
   assert(type(calls.button_state)=='function'and type(calls.equipment_sound)=='function'
    and calls.executable(targets.equip_state)and calls.executable(audio.entry),'native Equip feedback backend unavailable')
   local committed,why=self:commit_snapshot(catalog_result);assert(committed,why)
   assert(committed.profile_armor_id==id and committed.controller_armor_id==id
    and not committed.pending_nonarmor,'armor changed before Equip feedback')
   local ctx=detail_context();local button=ctx.detail_widget+Detail.equip_button
   local kit=ident(u32(ctx.watch(ctx.detail_widget+Detail.model+Model.kit,4),0))
   assert((kit==id or kit==shown_id)and catalog_result.verify_owned({id})==true,'selected armor changed before Equip feedback')
   local state=ctx.watch(button+Layout.equip_button.state,4)
   local offer=u32(ctx.watch(ctx.detail_widget+Detail.shown_offer,4),0)
   assert(offer and offer~=0 and audio.offers_global==progression_global,'native equipment sound offer unavailable')
   local progression=assert(pointer(ctx.watch(progression_global,8)),'native audio progression unavailable')
   local offer_count=u32(ctx.watch(progression+Progression.offer_count,4),0)
   assert(offer_count>=1 and offer_count<=Progression.offer_capacity,'native audio offer bounds rejected')
   local offers=ctx.watch(progression+Progression.offers,offer_count*Progression.offer_stride);local matched=false
   -- The sound is the worn armor's: with a card's own record on screen, the
   -- offer the sound is asked for is one of the worn record itself.
   local sound_offer=kit==id and offer or nil
   for i=0,offer_count-1 do
    local value,item=u32(offers,i*Progression.offer_stride+Progression.offer_id),ident(u32(offers,i*Progression.offer_stride+Progression.offer_kit))
    if value==offer then
     assert(item==kit,'native audio offer points to another item');matched=true
    end
    if value~=0 and item==id then sound_offer=sound_offer or value end
   end
   assert(matched,'native audio offer has no item mapping')
   assert(sound_offer,'native equipment sound offer unavailable')
   local catalog=assert(pointer(ctx.watch(audio.catalog_global,8)),'native audio catalog unavailable')
   local header=ctx.watch(catalog,Layout.item_catalog.header_size);local entries,count=pointer(header,Layout.item_catalog.entries),u32(header,Layout.item_catalog.count)
   local record=catalog_result.records[id]
   assert(entries and count>0 and count<=4096 and record and record.slot_address
    and record.slot_address>=entries and record.slot_address<entries+count*Layout.item_catalog.entry_size
    and (record.slot_address-entries)%Layout.item_catalog.entry_size==0 and pointer(ctx.watch(record.slot_address,Layout.item_catalog.entry_size))==record.address
    and record.category==category and ident(u32(ctx.watch(record.address+ArmorRecord.item_id,4),0))==id
    and u32(ctx.watch(record.address+ArmorRecord.category,4),0)==category,
    'native equipment audio category differs from the verified equipment')
   local profile=ctx.watch(ctx.profile_address,ctx.profile_size)
   assert(ctx.unchanged()and self:verify_commit(committed)and code_current(),'Equip feedback context changed')
   if u32(state,0)==Layout.equip_button.equipped then return {status='native_equipped_feedback_already_set',sound_played=false}end
   assert(calls.button_state(targets.equip_state,button,Layout.equip_button.equipped)~=false,'native equipped state rejected')
   local current=detail_context()
   assert(current.owner==ctx.owner and current.grid==ctx.grid and code_current()
    and read(ctx.profile_address,ctx.profile_size)==profile and u32(read(button+Layout.equip_button.state,4),0)==Layout.equip_button.equipped,
    'native equipped button readback differs')
   assert(calls.equipment_sound(audio.entry,ctx.grid,sound_offer)~=false,'native equipment sound rejected')
   return {status='native_equipped_feedback_verified',sound_played=true}
  end)
  if not ok then return nil,tostring(result)end;return result
 end
 function self:commit_capabilities()
  return {commit_verified=self.phase=='ready'and commit_info~=nil and code_current(),cache_layout_verified=false}
 end
 -- `opts.reconcile` takes the snapshot for a profile reconcile (commit_worn):
 -- an armor-category commit whose protected context masks all three equipment
 -- fields, because all three may be brought to what the actor already wears.
 -- `opts.view` is the catalog of the tab the Armory is showing: the grid view is
 -- identity-verified only against that tab's catalog, while the committed
 -- profile is one buffer whatever tab is up, so an armor-category commit may
 -- take its view through the helmet or cape catalog.
 function self:commit_snapshot(catalog_result,opts)
  local ok,result=pcall(function()
   assert(self.phase=='ready'and commit_info and code_current(),'native Armory commit proof unavailable')
   local view,why=self:snapshot(opts and opts.view or catalog_result);assert(view,why)
   assert(view.native_view_mode==View.single and view.identity_mapping_verified,'verified native Armor context required')
   local category=catalog_result.category or 0
   assert(category==Category.armor or category==Category.helmet or category==Category.cape,'unsupported equipment category')
   local offset=category==Category.helmet and Loadout.helmet or category==Category.cape and Loadout.cape or Loadout.armor
   local reconcile=type(opts)=='table'and opts.reconcile==true
   assert(not reconcile or category==Category.armor,'a profile reconcile is an armor-category commit')
   local function mask_armor(raw)
    if reconcile then return raw:sub(1,Loadout.helmet)..raw:sub(Loadout.armor+5)end
    return raw:sub(1,offset)..raw:sub(offset+5)
   end
   local ctx=assert(snapshots[view]);local watch=ctx.watch
   assert(category==Category.armor or view.native_category==category,'Accessory picker category changed')
   if ctx.payload then
    assert(not reconcile,'profile reconcile requires the ship Armory')
    assert(view.native_category==category,'Equipment picker category changed before Apply')
    assert(targets.deployment_commit,'Equipment Apply unavailable')
    local players=assert(pointer(watch(commit_info.players_global,8)),'Equipment players unavailable')
    local n=u32(watch(players+Players.count,4),0);assert(n>=1 and n<=Players.capacity,'Equipment player bounds rejected')
    local local_player=assert(pointer(watch(players+Players.local_player,8)),'Equipment local player unavailable')
    assert(u32(watch(local_player+Players.player_id,4),0)==ctx.player_id,'Equipment local player changed')
    local flags=u32(watch(players+Players.flags,4),0)
    assert(math.floor(flags/Players.flag_bit_3)%2==0 and math.floor(flags/Players.flag_bit_11)%2==0,'Unready before applying a variant')
    local payload=watch(ctx.payload,Payload.size)
    local profile_slot=watch(targets.deployment_commit.profile_global,8)
    local profile=assert(pointer(profile_slot),'Equipment profile unavailable')
    local key=tostring(ctx.owner)..':'..tostring(ctx.payload)..profile_slot
    if key~=commit_session_key then commit_session_key=key;commit_session={}end
    local payload_offset=category==Category.helmet and Payload.helmet or category==Category.cape and Payload.cape or Payload.armor
    local armor=ident(u32(payload,payload_offset))
    local out={session=commit_session,local_player_id=ctx.player_id,controller_armor_id=armor,profile_armor_id=armor,
     other_key=payload:sub(1,payload_offset)..payload:sub(payload_offset+5),pending_nonarmor=false}
    assert(ctx.unchanged()and code_current(),'Equipment snapshot changed')
    commit_snapshots[out]={category=category,ctx=ctx,payload=payload,profile=profile,player_id=ctx.player_id}
    return out
   end
   local old,current=watch(ctx.owner+Armory.committed,Loadout.size),watch(ctx.owner+Armory.pending,Loadout.size)
   local mirrors=watch(ctx.owner+Armory.mirrors,Armory.mirrors_size)
   local settings_slot=watch(commit_info.settings_global,8);local settings=assert(pointer(settings_slot),'native settings unavailable')
   local settings_fields=watch(settings+Settings.equipment,Settings.equipment_size)
   local player_slot=watch(commit_info.players_global,8);local players=assert(pointer(player_slot),'local-player manager unavailable')
   local counts=watch(players+Players.count,8);local n,local_count=u32(counts,0),u32(counts,Players.local_count-Players.count)
   assert(n>=1 and n<=Players.capacity and local_count>=1 and local_count<=Players.capacity,'local-player bounds rejected')
   local player=assert(pointer(watch(players+Players.local_player,8)),'local player unavailable')
   local player_id=u32(watch(player+Players.player_id,4),0);assert(player_id~=NONE,'local player sentinel rejected')
   local key=tostring(ctx.owner)..':'..settings_slot..player_slot..packed_u32(player_id)
   if key~=commit_session_key then commit_session_key=key;commit_session={}end
   local out={session=commit_session,local_player_id=player_id,
    controller_armor_id=ident(u32(current,offset)),profile_armor_id=ident(u32(old,offset)),
    profile_helmet_id=ident(u32(old,Loadout.helmet)),profile_cape_id=ident(u32(old,Loadout.cape)),
    other_key=mask_armor(old)..mask_armor(current)..mirrors..settings_fields,
    pending_nonarmor=mask_armor(old)~=mask_armor(current)or mirrors~=settings_fields}
   assert(ctx.unchanged()and code_current(),'commit snapshot changed')
   commit_snapshots[out]={category=category,reconcile=reconcile,ctx=ctx,current=current,old=old,mirrors=mirrors,settings=settings,settings_fields=settings_fields,player_id=player_id}
   return out
  end)
  if not ok then return nil,tostring(result)end;return result
 end
 function self:verify_commit(snapshot)
  local saved=commit_snapshots[snapshot]
  if not saved then return false end
  local ok,value=pcall(function()return code_current()and saved.ctx.unchanged()end)
  return ok and value==true
 end
 function self:commit_owned(id,expected,catalog_result)
  local attempted=false;local changed=false;local saved
  local category=catalog_result and catalog_result.category or 0
  local offset=category==Category.helmet and Loadout.helmet or category==Category.cape and Loadout.cape or Loadout.armor
  local function mask_armor(raw)return raw:sub(1,offset)..raw:sub(offset+5)end
