  if not(row.kind=='clothing'and type(owner)=='table'and type(owner.player_record)=='function'
   and type(owner.depicts)=='function'and type(owner.worn)=='function')then return nil end
  local record=owner:player_record(row.slot)
  local look=record and owner:worn(record)and owner:depicts(record)
  if look and look.uuid==row.look.uuid then return record,look end
  return nil
 end
 if not(row and row.kind=='clothing'and row.home and type(owner)=='table'
  and type(owner.worn)=='function'and type(owner.depicts)=='function'and owner:worn(row.home)==true)then return nil end
 local look=owner:depicts(row.home)
 if look and row.look and look.uuid==row.look.uuid then return row.home,look end
end
