 local row=row_of(catalog,label)
 local owner=current_owner()
 local look=type(owner)=='table'and type(owner.depicts)=='function'and record and owner:depicts(record)
 local live,worn=worn_clothing(owner,row)
 local wanted=live and record==live and worn.uuid..':'..worn.word or row and row.key or nil
 return wanted,look and look.uuid..':'..look.word or nil
end
