end)()
local PreviewPixels = (function()
-- The saved back-buffer frame and the stored cell's checksum.
--
-- The only pixel export the engine offers safely is the back buffer
-- (Application.save_render_target('back_buffer', path), research/109), as a
-- DX10 DDS file. This module reads its header; the stored cells are checked
-- with the checksum here.
--
-- Pure functions over strings; no engine, no files.
local M={}
local ffi=require('ffi')
M.HEADER=148           -- 'DDS ' + 124-byte header + 20-byte DX10 extension
local function u32(s,o)local a,b,c,d=s:byte(o+1,o+4);return a+b*256+c*65536+d*16777216 end
-- The saved frame's size, from its first 148 bytes. The file names RGBA8 but
-- stores blue first (seen against the game window, research/110 section 7);
-- rows run top to bottom.
function M.dds(header)
 if type(header)~='string'or #header<M.HEADER then return nil,'capture header is short'end
 if header:sub(1,4)~='DDS 'or u32(header,4)~=124 then return nil,'not a DDS capture'end
 if header:sub(85,88)~='DX10'or u32(header,128)~=28 then return nil,'capture is not 8-bit RGBA'end
 local height,width=u32(header,12),u32(header,16)
 if width<512 or height<512 or width>16384 or height>16384 then return nil,'capture size out of bounds'end
 return{width=width,height=height,bytes=M.HEADER+width*height*4}
end
-- FNV-1a over a pixel payload, as eight hex digits: the stored cell's check.
function M.checksum(pixels)
 local bxor=require('bit').bxor
 local p=ffi.cast('const uint8_t *',pixels);local hash=0x811c9dc5
 for i=0,#pixels-1 do
  hash=bxor(hash,p[i]);if hash<0 then hash=hash+4294967296 end
  -- hash * 0x01000193 modulo 2^32, in halves a double holds exactly.
  local low=hash%65536;local high=(hash-low)/65536
  hash=(((high*0x0193+low*0x0100)%65536)*65536+low*0x0193)%4294967296
 end
 return string.format('%08x',hash)
end
-- The checksum checked where it runs, over enough bytes for the loop to be
-- compiled (the game's LuaJIT has miscompiled hot loops before, research/110);
-- the long answer was computed outside Lua. A Lua that computes it
-- differently must not verify or store images.
function M.selftest()
 local page=ffi.new('uint8_t[?]',8192)
 for i=0,8191 do page[i]=(i*7+3)%256 end
 if M.checksum('foobar')~='bf9cf968'or M.checksum('')~='811c9dc5'or M.checksum(ffi.string(page,8192))~='d66e5dc5'then return nil,'checksum'end
 return true
end
return M

end)()
local PreviewStore = (function()
-- Saved-look thumbnails on disk, keyed by what the image depends on.
