 if tile~=nil and not(type(tile)=='number'and tile%2==0 and tile>M.CELL and tile<=M.MAX_TILE)then return nil,'a tile is larger than a cell, and even'end
 local key=table.concat({M.RENDERER,style,parts.slot,parts.body,parts.uuid,parts.content,parts.word},'|')
