end
function M.parts(key)
 if type(key)~='string'then return nil end
 local rest,tile=key:match('^(.*)|tile%-(%d+)$')
 if rest then key=rest;tile=tonumber(tile)end
 local base=key:match('^(.*)|section%-helmet%-v1$');local view=base and'section'or nil
 local renderer,revision,slot,body,uuid,content,word=(base or key):match('^([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)$')
 if renderer~=M.RENDERER then return nil end
 local style;for name,id in pairs(M.STYLES)do if id==revision then style=name end end
 if not style then return nil end
 local p={slot=slot,body=body,uuid=uuid,content=content,word=word,style=style,view=view,tile=tile}
 local whole=M.key(p);if not whole or whole~=key..(tile and'|tile-'..tile or'')then return nil end
