local function cell_rows(cell)
 local x,y=cell%M.COLUMNS,math.floor(cell/M.COLUMNS)
 local rows={}
 for row=0,M.CELL-1 do rows[row+1]=((y*M.CELL+row)*M.PAGE+x*M.CELL)*4 end
