   local value=tonumber(line:match('^G (%d+)$'))
   if seen_generation or not value or value>M.MAX_GENERATION then return {},'invalid preview generation',0 end
   generation=value;seen_generation=true
  elseif line:sub(1,2)=='T 'then
   local tile,size,sum,epoch,key=line:match('^T (%d+) (%d+) (%x%x%x%x%x%x%x%x) (%d+) (%S+)$')
