   else page,cell,sum,epoch,key=line:match('^E (%d+) (%d+) (%x%x%x%x%x%x%x%x) (%d+) (%S+)$')end
   page,cell,epoch=tonumber(page),tonumber(cell),tonumber(epoch)
   local slot=page and page<100000 and cell<M.PER_PAGE and page*M.PER_PAGE+cell
   local parts=slot and key and M.parts(key)
