 local count=0;for _ in pairs(entries)do count=count+1 end
 local revision,page_revisions=0,{}
 local self=setmetatable({problem=problem},{__index=M})
 local function copy_entries()
  local out={};for key,entry in pairs(entries)do out[key]=entry end;return out
 end
 local function free_slot()
  local taken={};for _,entry in pairs(entries)do if entry.page then taken[entry.page*M.PER_PAGE+entry.cell]=true end end
  local slot=0;while taken[slot]do slot=slot+1 end
  return math.floor(slot/M.PER_PAGE),slot%M.PER_PAGE
