end)()
local NativePreviewPixels = (function()
-- Native thumbnail output, not the old default/HDR render cutout.
-- ui_3d_debug exports blue-first premultiplied RGB and true MSAA alpha in
-- the colour quadrant. Native RGB is already atlas-input RGB: NO display
-- curve, polynomial, colour grade, or inverse GUI transfer belongs here.
-- Pure functions; no engine calls, file access, reference images or resizing
-- to an appearance-dependent bounding box.
local M={CELL=240,ARMOR_TOP=7.5,RECIPE='native-ldr-msaa-v1'}
local ffi=require('ffi')
local function integer(n,lo,hi)return type(n)=='number'and n==n and n>=lo and n<=hi and n%1==0 end
local function finite(n)return type(n)=='number'and n==n and n>-math.huge and n<math.huge end
local function byte(n)return math.floor(math.max(0,math.min(255,n))+0.5)end
-- tile_rect is {left,top,right,bottom}, exclusive ends, in the FULL DDS
-- back-buffer coordinates. Equivalently supply color={x=,y=} and side=.
-- Never infer/centre a tile: the renderer must provide the captured slot.
-- Example: donor tile8 on2560x1440 -> {240,960,480,1200}.
function M.plan(width,height,size,capture)
 if not(integer(width,2,16384)and integer(height,2,16384))or width%2~=0 or height%2~=0 then return nil,'invalid frame dimensions'end
 size=size or M.CELL
 if not integer(size,1,2048)then return nil,'invalid cell size'end
 if type(capture)~='table'then return nil,'native capture tile required'end
 local x,y,side
 if type(capture.tile_rect)=='table'then
  local t=capture.tile_rect
  if not(integer(t[1],0,width)and integer(t[2],0,height)and integer(t[3],0,width)and integer(t[4],0,height))then return nil,'invalid native tile rectangle'end
  x,y,side=t[1],t[2],t[3]-t[1]
  if t[4]-t[2]~=side then return nil,'native capture tile must be square'end
 elseif type(capture.color)=='table'then x,y,side=capture.color.x,capture.color.y,capture.side
 else return nil,'native capture tile required'end
 if not(integer(x,0,width/2)and integer(y,height/2,height)and integer(side,1,8192))or x+side>width/2 or y+side>height then return nil,'native tile outside colour quadrant'end
 if side%size~=0 then return nil,'native tile requires integer area reduction'end
 local alpha_source=capture.alpha_source or'color'
 if alpha_source~='color'and alpha_source~='coverage'then return nil,'unknown native alpha source'end
 local coverage
 if alpha_source=='coverage'then
  local c=capture.coverage or{x=x+width/2,y=y}
  if not(type(c)=='table'and integer(c.x,width/2,width)and integer(c.y,height/2,height))or c.x+side>width or c.y+side>height then return nil,'native coverage outside depth quadrant'end
