 local function addr(v)return Calls.address(api,v)end
 local function unit_id(u)return(n.api.calls or{}).model_unit_id and n.api.calls.model_unit_id(u)or math.floor(addr(u)/Layout.handle.unit_id_divisor)end
 local function read(address,size)
