 -- Everything the build has to offer, once: code where the offsets come
 -- from, names the engine is handed, and the calls the game's Lua has.
 local function verify()
  if verified then return end
  assert(n.api.module(nil),'process module unavailable')
  for _,s in ipairs(SIGNATURES)do
   assert(n.intact(s.name),'another game build: model render code differs')
  end
  assert(names:template(Templates.default)and names:template(Templates.ui_3d)and names:template(M.COMPOSITE),'viewport templates absent')
  assert(names:generator(Passes.mask_depth,{Resources.output_target,Resources.depth_stencil},{Resources.output_rt}),'mask pass changed')
  for _,name in ipairs({Resources.output_target,Resources.depth_stencil})do assert(names:resource(name),'render resource absent: '..name)end
  assert(E.Application.can_get(Layout.resource_types.shading_environment,assert(names:environment(),'default environment unnamed')),'default environment not loaded')
  for _,f in ipairs({'set_frustum','set_projection_type','set_near_range','set_far_range'})do assert(type(E.Camera[f])=='function','camera call absent: '..f)end
  assert(type(E.Viewport.register_render_resource)=='function','viewport resource binding absent')
  assert(type(E.Application.create_render_target)=='function'and type(E.Renderer.run_resource_generator)=='function','render calls absent')
  for _,f in ipairs({'num_lights','local_rotation','num_meshes','mesh','set_mesh_visibility'})do assert(type(E.Unit[f])=='function','unit call absent: '..f)end
  assert(type(E.Light.intensity)=='function'and type(E.Quaternion.to_elements)=='function','scene controls absent')
