 -- The diffuse texture of the model image's material, or nil.
 local function diffuse(material)
  local head=read(material,Material.head_size)
  local count=u32(head,Material.slot_count);local list=pointer(head,Material.slots)
  if count<1 or count>64 or not list then return nil end
  local rows=read(list,count*Material.slot_stride)
