  local stretch,scale_x,scale_y=-view[0],proj[0],proj[9]
  if not(finite(stretch)and stretch>.2 and stretch<8 and finite(scale_x)and scale_x>.05 and scale_x<200
   and finite(scale_y)and scale_y>.05 and scale_y<200
   and math.abs(view[5]+1)<1e-4 and math.abs(view[10]-1)<1e-4 and math.abs(view[15]-1)<1e-4
   and math.abs(view[1])<1e-4 and math.abs(view[4])<1e-4 and math.abs(proj[7]-1)<1e-4)then return false end
