  assert(world and world~=E.Application.main_world(),'model world not listed')
  local element=c.detail+M.WIDGET+M.IMAGE
  local flags=n.u32(element+Element.flags)
  assert(flags%Element.kind_high-flags%Element.kind_low==Element.kind_image,'model image is not an image')
