  local d=read(game,Target.head_size)
  assert(u32(d,Target.width)==width and u32(d,Target.height)==height,'canvas is not the back-buffer size')
  local s={owner=c.owner,detail=c.detail,category=c.category,ui=ui,real=real,world=world,element=element,material=material,
   target=target(width,height),width=width,height=height,lights={},own_lights={},frames=0,skipped=0}
