   s.env=E.World.create_shading_environment(world)
   local offered=names:environment_names(addr(s.env));E.ShadingEnvironment.update(s.env)
   for name,value in pairs(settings.scalars or{})do
    assert(type(name)=='string'and offered.variables[host.ids.id32(name)]and finite(value),'unknown environment setting '..tostring(name))
    E.ShadingEnvironment.set_scalar(s.env,name,value)
   end
   if settings.native_ibl~=false then
    s.restore_ibl=host.ibl(s.env,host.environment.borrow{native=n,engine=E,world=world})
   end
   s.camera_unit=E.World.spawn_unit(world,E.IdString64.from_hex(M.CAMERA),E.Vector3(0,0,0),E.Quaternion.from_elements(0,0,0,1))
   s.camera=E.Unit.camera(s.camera_unit,1)
