   E.Camera.set_near_range(s.camera,M.NEAR);E.Camera.set_far_range(s.camera,M.FAR)
   E.Unit.set_local_rotation(s.camera_unit,1,E.Quaternion.look(E.Vector3(0,-1,0),E.Vector3(0,0,1)))
