  -- Its lights are disabled and the image retains the last complete frame.
  if busy then
   if session then session.armed=false;unstage(session)end
   return
  end
  local ok,why=pcall(function()
   if session then session.armed=false end
   if session and(session.owner~=c.owner or session.element~=c.detail+M.WIDGET+M.IMAGE or n.ptr(n.at('ui_scene_manager'))~=session.ui or n.ptr(session.ui+M.WORLD)~=session.real)then
