 assert(body_type==BodyType.muscle or body_type==BodyType.lean,'explicit native body type 0 or 1 required')
 assert(type(record.bodies)=='table'and #record.bodies>=1 and #record.bodies<=Catalog.kit.max_bodies,'invalid verified body descriptors')
 local gathered,count=0,0
 local sums={armor_rating=0,speed=0,stamina_regen=0}
 for _,body in ipairs(record.bodies)do
  if gathered==Catalog.card_gather_limit then break end
  assert(type(body)=='table'and uint(body.type),'invalid body descriptor')
  if body.type==body_type or body.type==BodyType.any then
   assert(type(body.pieces)=='table'and #body.pieces<=Catalog.body.max_pieces,'invalid verified piece array')
   for _,piece in ipairs(body.pieces)do
    if gathered==Catalog.card_gather_limit then break end
