    assert(type(piece)=='table'and uint(piece.slot),'invalid piece slot')
    local kind=piece.kind;if kind==nil then kind=piece.type end
    assert(uint(kind),'invalid piece kind')
    if kind==Kind.armor and piece.slot>=Slot.torso and piece.slot<=Slot.right_shoulder and piece.slot~=Slot.hips then
     assert(uint(piece.weight)and piece.weight<=Weight.heavy,'Armor-card weight is outside the proved three-entry tables')
