 if name=='NativeGridPresentation'then return NativeGridPresentation or error('module is not bundled: src.native_grid_presentation')end
 if name=='VariantSession'then return VariantSession or error('module is not bundled: src.variant_session')end
 if name=='ArmorRefresh'then return ArmorRefresh or error('module is not bundled: src.armor_refresh')end
 if name=='ArmorRefreshBridge'then return ArmorRefreshBridge or error('module is not bundled: src.armor_refresh_bridge')end
 if name=='VariantWizard'then return VariantWizard or error('module is not bundled: src.variant_wizard')end
 if name=='UiWorkflow'then return UiWorkflow or error('module is not bundled: src.ui_workflow')end
 if name=='ClothingCatalog'then return ClothingCatalog or error('module is not bundled: src.clothing_catalog')end
