   screen.kind=sample.kind;screen.shown_category=nil
   clear();screen.token=sample.token;report('screen.detected',sample.kind)
   if sample.anchor then
    report('screen.anchor',table.concat({sample.anchor.x,sample.anchor.y,sample.anchor.w,sample.anchor.h},','))
   end
   local active=patch_active()
   for category=0,2 do local tab=tabs[category];if tab and tab:is_active()then active=true end end
   if not active then armory.discard_catalog()end
  end
  local catalog_ok,catalog_why=true,nil
  if not catalog_stepped then catalog_ok,catalog_why=pcall(catalog.update)end
  if not catalog_ok and not catalog.failed then catalog.fail(tostring(catalog_why))end
  catalog.refresh_ownership(now)
  armory.init_helmets()
  -- Body armor's reading of the list is also how the screen is read:
  -- which list is up says which tab has the frame.
  local observed=armor_tab:observe(now)
  local input=fs.sample_input()
  if catalog.result and bridge and bridge.phase=='ready' then
   -- The profile reconcile runs on every tab, through the body
   -- session: it alone is stepped off its own tab, and only while
   -- that commit is in flight. A tab's own Apply never outlives its
   -- list, since a hidden tab leaves its session.
   if observed and observed.kind==Picker.kind_armor then
    reconcile(now,screen.token)
    if st.session and st.session:busy() and not observed.identity_mapping_verified then
     st.session:step(now)
    end
   end
   -- An unreadable list changes nothing: the tab that had the frame keeps it.
   -- False while a list that is no tab's is up; nil until one was read.
   local category=screen.shown_category
   if category==nil then category=0 end
   if observed then category=observed.kind==Picker.kind_armor and observed.native_view_mode==View.single and(observed.native_category or 0)end
   screen.shown_category=category
   local shown
   for index=0,2 do
    local tab=tabs[index]
    if tab then
     if index==category and tab:available()then shown=tab else tab:hide(now)end
    end
   end
   if shown and shown~=armor_tab then
    wipe()
    shown:observe(now)
    shown:frame(now,sample,input)
    return
   end
   screen.armor_shown=shown==armor_tab
   if not shown and(category==1 or category==2)and bridge.custom_headers then
    -- Native header widgets are recycled between gear categories.
    -- A slot with no custom provider still needs its own stock label.
    bridge:custom_headers(0,false,{})
   end
   local p=panel();if p then p.preview_step(now)end
  else screen.armor_shown=true end
  local p=panel()
  if p then p.refresh_plan()end
  catalog.refresh_stats(now)
  -- Body armor has the frame, or no tab has: the tab first, and the
  -- development panel below only while the tab has no creator of its own.
  if screen.armor_shown then armor_tab:frame(now,sample,input)end
  if not input then clear();return end
  if st.flow then return end
  if p then p.frame(now,sample,input)end
 end
 -- Every tab guards its own cards before the game reads this frame's
 -- input. A guard that fails has taken its creator down: this frame is
 -- withheld once; a failing guard is never repeated every frame.
 k:step{phase='pre',name='armory.guard',order=110,run=function()
  if stopped or screen.active==false then return end
  for category=0,2 do
   local tab=tabs[category]
   if tab and not tab:before(fs.sample_input)then
    status('CREATOR PAUSED - reopen the Armory after input capture recovers')
