 -- keeps running.
 k:step{phase='post',name='armory.tick',order=20,breaker={limit=3},
  run=function()
   -- Unprotected: the scheduler takes the traceback where tick failed. A frame
   -- that fails is not a profile sample.
   local began=os.clock()
   tick()
   runtime.profile.tick=runtime.profile.tick+os.clock()-began;runtime.profile.frames=runtime.profile.frames+1
  end,
  on_error=function(reason,count)
   local p=panel();if p then pcall(p.wipe);p.reset()end
   report('runtime.error',reason);report('frame',frame)
   next_attempt=fs.now()+5000*count
  end,
  on_stop=function()
   stopped=true;status('STOPPED - see HD2Transmog.log for compatibility error')
  end}
 k:on_shutdown('armory.stop',function()stopped=true end,10)
 k:on_shutdown('armory.tabs',function()
  for category=0,2 do local tab=tabs[category];if tab then pcall(tab.shutdown,tab)end end
 end,40)
 k:on_shutdown('armory.grid',function()
  if bridge and bridge.release_view then bridge:release_view()end
 end,70)
 k.health:define('game.ui',{owner='src/game/compat_spec.lua',check=function()
  if not ui_adapter then return 'unknown','the Armory layout has not been read'end
  if ui_adapter.phase=='failed'then return 'degraded','Armory layout resolution failed: '..tostring(ui_adapter.failure)end
  if ui_adapter.phase~='ready'then return 'unknown','the Armory layout is still resolving'end
  return 'pass'
 end})
 k.health:define('game.grid',{owner='src/game/grid_symbols.lua',requires={'game.ui'},check=function()
  if not bridge then return 'unknown','the equipment grid has not been read'end
  if bridge.phase=='failed'and bridge.cold then return 'unknown','waiting for game code: '..tostring(bridge.failure)end
  if bridge.phase=='failed'then return 'degraded','equipment grid resolution failed: '..tostring(bridge.failure)end
  if bridge.phase~='ready'then return 'unknown','the equipment grid is still resolving'end
