 k:command('ui_status',function(args)
  local rows={'HD2TM_UI_STATUS 1'}
  if catalog.result then
   for _,name in ipairs({'armor','helmets','capes'})do
    local cat=name=='armor'and catalog.result or catalog.result[name]
    if cat then
     rows[#rows+1]='catalog.'..name..'.registered='..tostring(#(cat.registered_entries or{}))
     for key,value in pairs(cat.logical_availability or{})do
      rows[#rows+1]='catalog.'..name..'.'..key..'='..tostring(value):gsub('[\r\n]',' ')
     end
    end
   end
  end
