   rows[#rows+1]='diverkit.reason='..tostring(compat and compat.reason or'')
   for _,key in ipairs({'notice','apply_reason','status','selected','visible','collapsed'})do
    rows[#rows+1]='diverkit.'..key..'='..tostring(state and state[key]or''):gsub('[\r\n]',' ')
   end
  end
