local BootExtras = (function()
-- Stage `extras`: what the Armory picker gets on top of the list itself --
-- per-look card images, native detail text and the large model -- and the
-- public preview controls.
--
-- Provides: extras (the ArmoryExtras instance), extras.modules (the preview
-- and render modules by their short names).
-- Publishes: HD2Transmog.previews.
local M={name='extras',requires={'session','armory'}}
function M.start(k,env)
 local mods,runtime,report=env.modules,env.runtime,env.report
 local fs,engine,armory=k:need('fs'),k:need('engine'),k:need('armory')
 -- The instance is looked up each frame: it is bound after the game's update
 -- and this frame's list work, whoever provided it.
 k:step{phase='pre',name='extras.before',order=10,run=function(_,dt)
  -- Release the full-model render gate before simulation/streaming.
  local extras=k:service('extras')
  if extras and extras.before_update then extras:before_update(dt)end
 end}
 k:step{phase='post',name='extras.update',order=30,run=function()
  -- Native update and our list publication can replace a card's image.
  -- Bind saved images after both, before the GUI batches this frame.
  local extras=k:service('extras')
  if extras then extras:update()end
 end}
 k:on_shutdown('extras',function()
  local extras=k:service('extras');if extras then extras:shutdown()end
 end,50)
 if not mods.ArmoryExtras then return end
 local modules={Extras=mods.ArmoryExtras,Native=mods.ArmoryNative,Store=mods.PreviewStore,
  Pixels=mods.PreviewPixels,Previews=mods.ArmoryPreviews,Text=mods.NativeText,Ids=mods.IdString,Config=mods.ConstConfig,
  RenderConfig=mods.RenderConfig,Hook=mods.RenderHook,Render=mods.PreviewRender,NativePixels=mods.NativePreviewPixels,
  ActorPool=mods.PreviewActorPool,Actor=mods.PreviewActor,WorldGate=mods.PreviewWorldGate,WorldFlush=mods.PreviewWorldFlush,
  Backend=mods.PreviewFullBackend,Environment=mods.PreviewNativeEnvironment,Profiles=mods.PreviewNativeProfiles,
  Settings=mods.PreviewSettings,Colour=mods.PreviewColour,Cutout=mods.RenderCutout,
  Rebuild=mods.PreviewRebuild,Subjects=mods.PreviewSubjects,Service=mods.PreviewService,Identity=mods.ClothingIdentity,Compare=mods.ClothingCompare,
  ModelRender=mods.ArmoryModelRender}
 local extras=mods.ArmoryExtras.new{modules=modules,fs=fs,engine=engine,report=report,
  tabs=function()return armory.tabs end,grid=armory.grid,
  thumbnails=mods.VariantThumbnails,
  targets={}, -- render targets are never freed: one table for the session
  owner=function()return k:service('clothing.owner')end,
  clothing=function()return runtime.clothing end,
  materials=function()return k:service('clothing.materials')end,
  variant_default=function(label,slot)return k:need('clothing.variants').default(label,slot)end,
  -- Asked for when the native side starts, not at load.
  process=function()return k:need('process')end,
  -- Every fixed address the extras use is the game contract's answer.
  game_address=k:has('game')and k:need('game').address or nil}
 k:provide('extras',extras);k:provide('extras.modules',modules)
 runtime.previews={
  rebuild=function()armory.init_helmets();return extras:rebuild(true)end,
  fill_missing=function()armory.init_helmets();return extras:rebuild(false)end,
  resume=function()return extras:resume_rebuild()end,
  cancel=function()return extras:cancel_rebuild()end,
  status=function()return extras:status().rebuild end,
  get_style=function()return extras:get_style()end,
  set_style=function(style)return extras:set_style(style)end,
  get_model=function()return extras:get_model()end,
  set_model=function(choice)return extras:set_model(choice)end,
  capabilities=function(opts)return extras:capabilities(opts)end}
 k.health:define('armory.extras',{owner='src/armory_extras.lua',check=function()
  local seen=extras:status()
  if type(seen)~='table'then return 'unknown','the preview pipeline has not started'end
  if seen.off then return 'off',tostring(seen.off)end
  local parts={}
  for part,flag in pairs(type(seen.stopped)=='table'and seen.stopped or{})do if flag then parts[#parts+1]=tostring(part)end end
  if #parts>0 then table.sort(parts);return 'partial','stopped: '..table.concat(parts,', ')end
  if seen.render_off then return 'partial','rendering is off: '..tostring(seen.render_off)end
  return 'pass'
 end})
 k:command('rebuild_previews',function(args)
  local previews=assert(runtime.previews,'preview pipeline unavailable')
  local action=(args or''):match('^%s*(%S*)')
  local result,why
  if action=='status'then result=previews.status()
  elseif action=='cancel'then result,why=previews.cancel()
  elseif action=='resume'then result,why=previews.resume()
  elseif action=='missing'then armory.init_helmets();result,why=previews.fill_missing()
  else assert(action==''or action=='all','expected all | missing | status | cancel | resume')
   armory.init_helmets();result,why=previews.rebuild()end
  assert(result,why or'preview pipeline is not initialized')
  local text=string.format('phase=%s total=%d done=%d skipped=%d failed=%d pending=%d active=%d generation=%d',
   result.phase,result.total,result.done,result.skipped,result.failed,result.pending,result.active,result.generation)
  if result.waiting then text=text..' waiting='..result.waiting end
  if result.blocked then text=text..' blocked='..result.blocked end
  text=text..string.format(' render_requests=%d render_completed=%d render_failed=%d recipe=%s',
   result.render_requests or 0,result.render_completed or 0,result.render_failed or 0,tostring(result.recipe))
  assert(fs.write_atomic('debug-preview-rebuild.txt',text..'\n'));return text
 end)
 -- The large model's renderer, for a measurement: `full` or `game` chooses it
 -- (and is saved, as the option in the menu is); with nothing it is only asked.
 -- `pace 1|2|3` draws it on every first, second or third frame whatever the
 -- frame time is, `pace auto` lets the frame time decide again.
 k:command('preview_model',function(args)
  local choice,value=(args or''):match('^%s*(%S*)%s*(%S*)')
  local model=extras:parts().model
  if choice=='pace'then
   assert(model,'the full model renderer has not been made yet: open the picker first')
   assert(value=='auto'or tonumber(value),'the pace is 1, 2, 3 or auto')
   local ok,why=model:set_pace(value~='auto'and tonumber(value)or nil);assert(ok,why)
  elseif choice~=''then local ok,why=extras:set_model(choice);assert(ok,why);model=extras:parts().model end
  local seen=model and model:status()or{}
  return string.format('model=%s active=%s frames=%s held=%s skipped=%s binds=%s failures=%s every=%s forced=%s frame_ms=%s off=%s',
   extras:get_model(),tostring(seen.active==true),tostring(seen.frames or 0),tostring(seen.held or 0),tostring(seen.skipped or 0),
   tostring(seen.binds or 0),tostring(seen.failures or 0),tostring(seen.every or 1),tostring(seen.forced),
   seen.frame_ms and string.format('%.1f',seen.frame_ms)or'-',tostring(seen.off))
 end)
end
return M

end)()
local BootDiverKit = (function()
-- Stage `diverkit`: optional compatibility with DiverKit loadout presets. The
-- adapter finds DiverKit by behaviour, never by version; this stage supplies
-- what only the Armory side knows: how to capture the worn variant into a
-- preset and how to put one back on.
--
-- Provides: diverkit (the compatibility instance).
-- Publishes: HD2Transmog.diverkit_compat, which DiverKit reads.
local M={name='diverkit',requires={'session','armory'}}
function M.start(k,env)
 local mods,runtime,report=env.modules,env.runtime,env.report
 local fs,notice,status=k:need('fs'),k:need('notice'),k:need('status')
 local catalog,actor,store,armory=k:need('catalog'),k:need('actor'),k:need('store'),k:need('armory')
 local st,armor_tab,startup=armory.state,armory.armor_tab,armory.startup
 local EquippedState=mods.EquippedState
 local function patch_active()local p=k:service('panel');return p~=nil and p.active()==true end
 local compat=mods.DiverKitCompat.new{
  report=report,peer=runtime,identity=env.public,
  notice=function(message)
   runtime.diverkit_notice=message
   if message then notice.set(message);status(message)
   else status('DiverKit compatibility rechecked')end
  end,
  active=function()return startup.active==true or st.session and st.session:is_active()or false end,
  capture=function(armor)
   if startup.active then return nil,'Startup restoration is pending'end
   if not st.session then return false end
   local id='armor:'..armor:sub(3):lower()
   local record,why=st.session:export_equipped(id)
   if not record then return record,why end
   local logical=record.request.appearance_id:match('^clothing:')~=nil
   if logical then record.logical_id=record.request.appearance_id end
   local result=catalog.result
   if not EquippedState.matches(record,store.domain,id,result and result.context)then return nil,'Equipped variant was removed or changed'end
   local saved=store.domain.presets[record.label]
   return{version=logical and 2 or 1,label=record.label,appearance_id=record.request.appearance_id,
    stats_id=record.request.stats_id,passive_variant_id=record.request.passive_variant_id,
    variant_id=logical and saved and saved.id or nil}
  end,
  prepare=function(record,armor,driver)
   if store.locked or patch_active()or startup.active or st.session and st.session:busy()
    or st.flow and st.flow:is_open()then return nil,'Finish the current Transmog operation first'end
   if not catalog.result then catalog.update()end
   local result=catalog.result
   if not result then return nil,'Open Armor once to finish catalog verification, then retry'end
   local domain=store.domain
   local id='armor:'..armor:sub(3):lower()
   local request=record and{appearance_id=record.appearance_id,stats_id=record.stats_id,
    passive_variant_id=record.passive_variant_id,id=record.variant_id}or result.catalog[id]
   if not request then return nil,'Original armor is unavailable'end
   local logical=request.appearance_id:match('^clothing:')~=nil
   local intent=record and{label=record.label,request=request,target_id=id,version=record.version,
    logical_id=logical and request.appearance_id or nil}
   if logical then
    id=EquippedState.resolve_target(intent,result.context)
    if not id then return nil,'The saved clothing pack is unavailable or has no verified binding'end
   end
   if record and not EquippedState.matches(intent,domain,id,result.context)then
    return nil,'Saved Transmog variant was removed or changed; save the DiverKit preset again'
   end
   local allowed,reason=mods.AppearancePatch.compatible(result,request)
   if not allowed then return nil,reason end
   local donors={}
   for _,field in ipairs({'appearance_id','stats_id','passive_variant_id'})do
    local donor
    for kit_id,kit in pairs(result.catalog)do
     if result.owned[kit_id]and kit[field]==request[field]
      and(field=='appearance_id'or not kit_id:match('^clothing:'))then donor=kit_id;break end
    end
    if not donor then return nil,'A saved armor component is no longer owned'end
    donors[#donors+1]=donor
   end
   if result.verify_owned(donors)~=true then return nil,'Armor ownership changed'end
   local checked_driver=driver
   if logical then
    checked_driver={};for key,value in pairs(driver)do checked_driver[key]=value end
    -- Checked again when the operation commits, against the catalog and the
    -- saved variants as they are then.
    checked_driver.clothing_target=function()
     local live=catalog.result
     local target=EquippedState.resolve_target(intent,live.context)
     assert(target==id and EquippedState.matches(intent,store.domain,target,live.context),
      'Saved clothing binding or definition changed')
     assert(live.logical_compatible(request)==true,'Clothing entitlement or native donors changed')
     return target
    end
   end
   local player=actor.new()
   local bridge=mods.DiverKitBridge.new(checked_driver,player,result)
   local initial,why=bridge.snapshot();if not initial then return nil,why end
   if initial.pending_nonarmor or initial.request_armor_id~=initial.cache_armor_id then
    return nil,'Wait for equipment to finish changing'
   end
   local session=armor_tab:ensure_session();local begun=false
   return{
    begin=function(now)
     if begun then return nil,'Compatibility operation already started'end
     local accepted,error=session:external_begin(intent and intent.label or nil,request,now,bridge,not record)
     begun=accepted==true;return accepted,error
    end,
    poll=function(now)
     if not begun then return 'failed','Compatibility operation did not start'end
     session:step(now);runtime.armor_writes=session:is_active()
     if session.external_status=='complete'and record then
      local equipped,error=session:export_equipped(id)
      if not equipped then return 'failed',error or 'Variant composition did not verify'end
     end
     return session.external_status,session.external_error
    end,
    cancel=function(reason)if begun then session:external_cancel(reason)end end,
   }
  end,
 }
 runtime.diverkit_compat=compat
 k:provide('diverkit',compat)
 -- DiverKit is found by walking the update chain from the engine's callback.
 k:step{phase='pre',name='diverkit',order=30,
  run=function()
   local state=rawget(_G,'CodexLoadouts')
   if state or compat.status~='absent' then compat:step(fs.now(),rawget(_G,'update'),state)end
  end,
  on_error=function(reason)report('diverkit.error',reason)end}
 k:step{phase='post',name='diverkit.after',order=10,
  gate=function()return not armory.stopped()end,
  run=function()if compat.after_update then compat:after_update()end end}
 k:on_shutdown('diverkit',function()compat:shutdown()end,20)
 k.health:define('diverkit',{owner='src/diverkit_compat.lua',check=function()
  if compat.status=='absent'then return 'pass'end
  if compat.status=='unsupported'then return 'partial','DiverKit is present but not recognised: '..tostring(compat.reason or'')end
  return 'pass'
 end})
end
return M

end)()
local BootPanel = (function()
-- Stage `panel`: the development panel. An editor over the saved variants
-- with its own apply/reset transaction on native armor data, drawn only while
-- body armor's tab has no creator of its own. The test controls
-- (draft_variant, apply_variant, ...) share its domain, save and transaction
-- paths.
--
-- Provides: panel {surface, active(), wipe(), reset(), clear(),
-- drop_preview(), replan(all), refresh_plan(), preview_step(now),
-- frame(now, sample, input)}.
local M={name='panel',requires={'session','persistence','catalog','armory'}}
function M.start(k,env)
 local mods,runtime,report=env.modules,env.runtime,env.report
 local fs,engine,status,notice=k:need('fs'),k:need('engine'),k:need('status'),k:need('notice')
 local catalog,store,armory=k:need('catalog'),k:need('store'),k:need('armory')
 local State=mods.State
 local st=armory.state
 local surface=mods.Panel.new(engine)
 local editor=State.editor_new()
 local view={suspended=true,open=false,tab=store.tab,notice=notice.get(),saved=store.saved}
 local patch,patch_plan,patch_key,patch_active,patch_note
 local preview
 local previous_down,armed
 store.listen('restored',function()editor=State.editor_new()end)
 store.listen('saved',function()State.editor_saved(editor)end)
 local panel={surface=surface}
 function panel.active()return patch_active==true end
 function panel.wipe()surface:clear()end
 function panel.reset()previous_down,armed=nil,nil end
 function panel.clear()surface:clear();previous_down,armed=nil,nil end
 function panel.drop_preview()preview=nil end
 -- The plan was made against a catalog or an ownership that changed.
 function panel.replan(all)
  if all then patch=nil end
  patch_key,patch_plan=nil,nil
 end
 local function refresh_plan()
  if not mods.AppearancePatch or not mods.RuntimeWriter or not catalog.result or patch_active
   or st.session and st.session:is_active()then return end
  local request=editor.draft
  local key=request and table.concat({request.appearance_id,request.stats_id,request.passive_variant_id},'|')
  if key==patch_key then return end
  patch_key,patch_plan=key,nil
  if not request then return end
  if not patch then patch=mods.AppearancePatch.new(mods.RuntimeWriter.new(catalog.bridge(),catalog.result,k:need('process')))end
  patch_plan,patch_note=patch:plan(catalog.result,request)
  if patch_plan then patch_note='Apply variant, then equip the armor selected under Stats.'
  else report('variant.plan_rejected',patch_note);patch_note='This variant could not be prepared; see diagnostics.' end
 end
 panel.refresh_plan=refresh_plan
 local function queue_native_preview(target)
  local bridge=armory.grid()
  if not(target and bridge and bridge.select_kit and catalog.result)then return false end
  local snapshot=bridge:snapshot(catalog.result)
  if not snapshot or not snapshot.identity_mapping_verified then return false end
  local first=target
  if snapshot.selected_kit_id==target then
   local choices={}
   for id,owned in pairs(catalog.result.owned)do if owned and id~=target then choices[#choices+1]=id end end
   table.sort(choices);first=choices[1]or target
  end
  preview={target=target,first=first,phase='queued',deadline=fs.now()+15000}
  return true
 end
 local function apply_variant()
  assert(patch and patch_plan and not patch_active,'No verified variant transaction is ready')
  local done,evidence=patch:apply(patch_plan);patch_plan=nil;patch_key=nil
  patch_active=patch:is_active()~=false
  runtime.armor_writes=patch_active
  assert(done,evidence)
  runtime.armor_writes=true
  report('preview.readback',evidence.status);report('preview.source',evidence.source_id);report('preview.target',evidence.target_id)
  report('variant.passive',editor.draft and editor.draft.passive_variant_id)
  patch_note='Equip another armor, exit, then equip the Stats armor.'
  if queue_native_preview(evidence.target_id)then patch_note='Selecting the variant in the native preview...'end
  notice.set(patch_note)
  status('VARIANT PREPARED - equip another owned armor, exit Armory, reopen and equip the Stats armor')
  return 'Variant data readback verified; native preview still requires observation'
 end
 local function reset_variant()
  assert(patch,'No appearance preview exists')
  preview=nil
  local done,evidence=patch:reset();patch_active=patch:is_active()~=false;patch_key=nil
  assert(done,evidence)
  if evidence.target_id then queue_native_preview(evidence.target_id)end
  runtime.armor_writes=false;patch_note='Original armor restored - refresh the native preview'
  notice.set(patch_note);report('preview.reset',evidence.status)
  status('VARIANT RESET - original armor data restored')
  return patch_note
 end
 -- The native selection that shows a prepared variant: select another kit,
 -- then the target, and wait for each to be observed.
 function panel.preview_step(now)
  local pending=preview
  if not pending then return end
  if now>pending.deadline then
   preview=nil;report('variant.native_preview_error','native selection was not observed before deadline')
   notice.set('Select the Stats armor to inspect this variant.')
  elseif pending.phase=='queued' then
   local selected,reason=armory.grid():select_kit(pending.first,catalog.result)
   if selected then pending.phase='waiting';st.next_sample=0
   else preview=nil;report('variant.native_preview_error',reason);notice.set('Select the Stats armor to inspect this variant.')end
  elseif st.snapshot and st.snapshot.selected_kit_id==pending.first then
   if pending.first~=pending.target then pending.first=pending.target;pending.phase='queued'
   else
    preview=nil;patch_note=patch_active and 'Use the native Apply button to equip this variant.'or 'Original armor selected in the native preview.'
    notice.set(patch_note);report('variant.native_preview',pending.target)
   end
  end
 end
 -- One frame of the panel: its model is built only when it is drawn, since
 -- it walks the whole catalog.
 function panel.frame(now,sample,input)
  local result=catalog.result
  view.tab,view.notice,view.saved=store.tab,notice.get(),store.saved
  view.editor=State.editor_view(store.domain,editor,store.tab,result and result.context or{})
  view.active_variant=nil
  if patch_active and editor.draft and st.snapshot and st.snapshot.identity_mapping_verified
   and st.snapshot.selected_kit_id=='armor:'..editor.draft.stats_id:gsub('^native%-stats:','')then
   view.active_variant={label=editor.label,appearance_label=view.editor.appearance_label,
    stats_label=view.editor.stats_label,passive_label=view.editor.passive_label}
  end
  view.editor.can_apply=patch_plan~=nil and not patch_active
  view.editor.patch_active=patch_active==true
  view.editor.apply_note=patch_note
  if patch_active then
   for _,key in ipairs({'can_new','can_duplicate','can_discard','can_previous','can_next','can_save'})do
    view.editor[key]=false
   end
  end
  if not runtime.draw_started then runtime.draw_started=true;report('panel.stage','drawing first surface')end
  local shown=surface:draw(sample,view)
  if not shown then panel.reset();return end
  if not runtime.draw_finished then runtime.draw_finished=true;report('panel.stage','first surface completed')end
  local bridge=armory.grid()
  if input.down and surface.capture and surface:capture(input.x,input.y)
   and bridge and bridge.phase=='ready' then
   local consumed,reason=bridge:consume_select()
   if not consumed then report('grid.consume_error',reason);panel.reset();return end
   armory.latch_capture()
  end
  if not runtime.panel_seen then runtime.panel_seen=true;status('UI DRAWN - verify placement and interaction in game')end
  local target=surface:hit(input.x,input.y)
  if previous_down==nil then previous_down=input.down;armed=nil;return end
  if input.down and not previous_down then armed=target end
  if not input.down and previous_down then
   if armed and target==armed then
    if target=='toggle' then view.open=not view.open
    elseif store.tabs[target]then store.tab=target;store.saved=false;editor.detail_page=1
    elseif target=='save' then store.save()
    elseif target=='reload' then store.restore()
    elseif target=='apply_variant' then
     local done,why=pcall(apply_variant);if not done then notice.set('Preview rejected - see diagnostics');report('preview.error',why)end
    elseif target=='reset_variant' then
     local done,why=pcall(reset_variant);if not done then notice.set('Reset needs attention - see diagnostics');report('preview.reset_error',why)end
    else
     local handled,said,candidate,event=State.editor_action(store.domain,editor,target,store.tab,result and result.context or{})
     if handled then
      if said then notice.set(said)end
      store.saved=false
      if candidate then store.save(candidate)end
      if(target=='new_variant' or target=='duplicate_variant')and editor.dirty then view.open=true end
      if event then
       local acted,reason=pcall(function()
        if patch_active then reset_variant()end
        patch_key=nil;refresh_plan()
        if event.open_editor then view.open=true
        else apply_variant();view.open=false end
       end)
       if not acted then notice.set('Variant could not be selected - see diagnostics');report('variant.select_error',reason)end
      end
     end
    end
    report('ui.action',target)
   end
   armed=nil
  end
  previous_down=input.down
 end
 k:provide('panel',panel)
 k:on_shutdown('panel.surface',function()surface:clear()end,30)
 k:on_shutdown('panel.transaction',function()
  if not patch_active then return end
  local restored,reason=pcall(reset_variant);report('shutdown.preview_reset',restored and reason or 'session no longer available')
 end,80)
 local function variant_status()
  local domain=store.domain
  local lines={'HD2TM_VARIANT_STATUS 1','version '..runtime.version,
   'catalog_ready '..tostring(catalog.result~=nil),
   'active '..tostring(patch_active==true),'label '..tostring(editor.label or ''),
   'dirty '..tostring(editor.dirty==true),'can_apply '..tostring(patch_plan~=nil and not patch_active)}
  lines[#lines+1]='native_thumbnail_binding '..tostring(st.thumbnail_verified)
  lines[#lines+1]='native_selected_kit '..tostring(st.snapshot and st.snapshot.selected_kit_id or '')
  for _,field in ipairs({'appearance_id','stats_id','passive_variant_id'})do
   lines[#lines+1]=field..' '..tostring(editor.draft and editor.draft[field]or '')
  end
  local labels={};for label in pairs(domain.presets)do labels[#labels+1]=label end;table.sort(labels)
  for _,label in ipairs(labels)do lines[#lines+1]='saved '..label end
  lines[#lines+1]='note '..tostring(patch_note or notice.get()or ''):gsub('[\r\n]',' ')
  assert(fs.write_atomic('debug-variant-status.txt',table.concat(lines,'\n')..'\n'))
  return 'Current variant and saved-section state recorded'
 end
 k:command('variant_status',variant_status)
 k:command('draft_variant',function(args)
  armory.require_editor(true)
  assert(not editor.dirty,'Save or discard the current draft first')
  local appearance,stats,passive,label=args:match('^(%S+) (%S+) (%S+)\n([^\r\n]+)$')
  assert(appearance and label,'Expected three stable identities followed by a variant name')
  local domain=store.domain
  local candidate=State.new{catalog=domain.catalog,owned=domain.owned}
  local selected,why=State.select(candidate,appearance,stats,passive);assert(selected,why)
  local draft=State.editor_new();draft.draft=candidate.requested
  local named,reason=State.editor_rename(domain,draft,label);assert(named,reason)
  editor=draft;view.open=true;patch_key=nil;refresh_plan()
  variant_status()
  return 'Owned independent choices loaded into the editable draft'
 end)
 k:command('select_variant',function(args)
  armory.require_editor(true)
  assert(not editor.dirty,'Save or discard the current draft first')
  local chosen=assert(store.domain.presets[args],'Saved variant was not found')
  editor=State.editor_new()
  editor.draft={appearance_id=chosen.appearance_id,stats_id=chosen.stats_id,passive_variant_id=chosen.passive_variant_id}
  editor.label,editor.source_label,editor.dirty=args,args,false
  view.open=true;patch_key=nil;refresh_plan();variant_status()
  return 'Saved variant selected'
 end)
 k:command('save_variant',function()
  local context=armory.require_editor(true)
  local handled,said,candidate=State.editor_action(store.domain,editor,'save_variant',store.tab,context)
  assert(handled and candidate,said or 'No editable variant to save')
  assert(store.save(candidate),'Variant save failed; previous file retained')
  variant_status();return 'Variant saved through the editor persistence path'
 end)
 k:command('apply_variant',function()armory.require_editor(false);refresh_plan();local result=apply_variant();variant_status();return result end)
 k:command('reset_variant',function()armory.require_editor(false);local result=reset_variant();variant_status();return result end)
 k:command('layout_trial',function(args)
  armory.require_editor(true)
  assert(args=='on' or args=='off','Expected on or off')
  catalog.result.render_trial=args=='on';patch=nil;patch_key=nil;refresh_plan()
  report('variant.unverified_render_trial',catalog.result.render_trial)
  return args=='on' and 'Explicit development trial enabled; rendering is not yet verified' or 'Development trial disabled'
 end)
 k:command('inspect_render_types',function()
  assert(surface.material_diagnostic,'Render diagnostics unavailable')
  local values=surface:material_diagnostic()
  local lines={'HD2TM_RENDER_TYPES 1'}
  for _,key in ipairs({'gui_present','material_type','ffi_available','void_pointer_cast'})do
   lines[#lines+1]=key..'='..tostring(values[key])
  end
  assert(fs.write_atomic('debug-render-types.txt',table.concat(lines,'\n')..'\n'))
  local adapter=armory.adapter()
  if mods.RenderProbe and adapter and adapter.phase=='ready' and surface.material_handle then
   local result,reason=mods.RenderProbe.inspect(engine,surface.material_handle,adapter:debug_bridge())
   fs.write_atomic('debug-material-box.txt',result and mods.RenderProbe.format(result)or tostring(reason)..'\n')
  end
  return 'Existing GUI material types recorded without addresses'
 end)
end
return M

end)()
local HD2TM_OWN = {CreatorController=CreatorController, ClothingCompare=ClothingCompare, DebugArmory=DebugArmory, ArmorStatSemantics=ArmorStatSemantics, ArmorStatResolver=ArmorStatResolver, NativeGridModel=NativeGridModel, NativeGridFocus=NativeGridFocus, NativeGridProducers=NativeGridProducers, NativeGrid=NativeGrid, NativeGridRenewal=NativeGridRenewal, NativeGridPresentation=NativeGridPresentation, ArmorySection=ArmorySection, ArmorRefreshBridge=ArmorRefreshBridge, VariantSession=VariantSession, DiverKitCompat=DiverKitCompat, DiverKitBridge=DiverKitBridge, VariantLayout=VariantLayout, VariantWizard=VariantWizard, VariantCards=VariantCards, VariantThumbnails=VariantThumbnails, PreviewPixels=PreviewPixels, PreviewStore=PreviewStore, NativePreviewPixels=NativePreviewPixels, PreviewRebuild=PreviewRebuild, PreviewSubjects=PreviewSubjects, PreviewService=PreviewService, PreviewActorPool=PreviewActorPool, PreviewWorldGate=PreviewWorldGate, PreviewWorldFlush=PreviewWorldFlush, PreviewActor=PreviewActor, PreviewNativeEnvironment=PreviewNativeEnvironment, PreviewNativeProfiles=PreviewNativeProfiles, PreviewFullBackend=PreviewFullBackend, PreviewColour=PreviewColour, PreviewSettings=PreviewSettings, ConstConfig=ConstConfig, RenderConfig=RenderConfig, RenderHook=RenderHook, RenderCutout=RenderCutout, PreviewRender=PreviewRender, ArmoryNative=ArmoryNative, ArmoryPreviews=ArmoryPreviews, NativeText=NativeText, ArmoryModelRender=ArmoryModelRender, ArmoryExtras=ArmoryExtras, ArmorySlot=ArmorySlot, ArmorBaseStats=ArmorBaseStats, PassiveIconGeometry=PassiveIconGeometry, PassiveIconDraw=PassiveIconDraw, UiLayout=UiLayout, WizardPanel=WizardPanel, UiWorkflow=UiWorkflow, Panel=Panel, AccessoryUi=AccessoryUi, BootArmory=BootArmory, BootExtras=BootExtras, BootDiverKit=BootDiverKit, BootPanel=BootPanel}
-- Last lines of the Armory addon (tools/build.py puts its modules above, as
-- locals, and lists them in HD2TM_OWN). The addon's modules join the
-- foundation's by name, its stages are declared and started, and the checks of
-- the game its parts need are handed to the game contract.
for name, module in pairs(HD2TM_OWN) do rawset(HD2TM_CORE, name, module) end
local env = HD2TM_KERNEL:need('env')
-- The modules an Armory tab is made of, looked up when the tab uses them.
env.tab_modules = setmetatable({}, {__index=function(_, name)
    return rawget(HD2TM_CORE, name)
end})
local game = HD2TM_KERNEL:service('game')
if game then
    game.declare('armory', GameArmorySymbols)
    game.declare('render', GameRenderSymbols)
end
for _, stage in ipairs({BootArmory, BootExtras, BootDiverKit, BootPanel}) do
    HD2TM_KERNEL:stage{name=stage.name, requires=stage.requires, owner='src/boot/'..stage.name..'.lua',
        start=function(k) return stage.start(k, env) end}
end
HD2TM_KERNEL:provide('addon.' .. HD2TM_ADDON, true)
HD2TM_KERNEL:start()
env.off = HD2TM_KERNEL:stopped_stages()
return true
